const ArtifactChild = z.union([
	CustomDef.ref,
	PhoneDef.ref,
	SMSDef.ref,
	MonitorDef.ref,
	PostItDef.ref,
	SocialPostDef.ref
]);

const VtkFlavorChild = z.union([
	MindscapeDef.ref,
	InterfaceDef.ref,
	DocumentDef.ref,
	ArtifactDef.ref,
	DialogueSpotlightDef.ref,
	ReactionSpotlightDef.ref,
	FailureAchievementDef.ref,
	MemoryDef.ref,
	EntranceDef.ref,
	ClashDef.ref
]);

